const $=s=>document.querySelector(s),show=id=>{document.querySelectorAll('.view').forEach(v=>v.classList.add('hidden'));$(id).classList.remove('hidden');window.scrollTo(0,0)};let state={},map,marker,selectedPlace;
$('.swap').onclick=()=>{const a=$('#origin'),b=$('#destination');[a.value,b.value]=[b.value,a.value]};
function initMap(){if(map)return;map=L.map('live-map',{zoomControl:false}).setView([37.5665,126.978],14);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© OpenStreetMap contributors',maxZoom:19}).addTo(map);map.on('click',e=>setPlace(e.latlng,'선택한 지도 위치'));}
function setPlace(latlng,name){selectedPlace={latlng,name};if(marker)marker.setLatLng(latlng);else marker=L.marker(latlng).addTo(map);$('#picker-help').textContent=`선택됨: ${name}`;$('#confirm-place').disabled=false;}
$('#map-picker-button').onclick=()=>{show('#picker-view');initMap();setTimeout(()=>map.invalidateSize(),50)};$('#picker-back').onclick=()=>show('#search-view');
$('#place-search').onsubmit=async e=>{e.preventDefault();const query=$('#place-query').value.trim(),results=$('#search-results');if(!query)return;results.innerHTML='<p>장소를 찾는 중...</p>';try{const res=await fetch(`https://nominatim.openstreetmap.org/search?format=jsonv2&limit=4&accept-language=ko&q=${encodeURIComponent(query)}`,{headers:{Accept:'application/json'}}),items=await res.json();results.innerHTML=items.length?items.map((x,i)=>`<button type="button" data-i="${i}">${x.display_name}</button>`).join(''):'<p>찾는 장소가 없어요. 지도에서 직접 선택해 보세요.</p>';[...results.querySelectorAll('button')].forEach(btn=>btn.onclick=()=>{const x=items[btn.dataset.i],point=L.latLng(x.lat,x.lon);map.setView(point,16);setPlace(point,x.display_name.split(',').slice(0,2).join(', '));results.innerHTML=''})}catch{results.innerHTML='<p>검색에 연결하지 못했어요. 지도를 눌러 목적지를 선택해 주세요.</p>'}};
$('#confirm-place').onclick=()=>{if(!selectedPlace)return;$('#destination').value=selectedPlace.name;show('#search-view')};
$('#route-form').onsubmit=e=>{e.preventDefault();const origin=$('#origin').value.trim(),destination=$('#destination').value.trim(),text=$('#condition').value.trim();state={origin,destination,text,...mobilityMock.analyze(text)};show('#loading-view');setTimeout(render,950)};
function render(){const routes=mobilityMock.select(state.score),best=routes[0];state.best=best;$('#route-title').textContent=`${state.origin}에서 ${state.destination}까지`;$('#map-origin').textContent=state.origin;$('#map-destination').textContent=state.destination;$('#guide-origin').textContent=state.origin;$('#guide-dest').textContent=state.destination;$('#analysis-summary').innerHTML=`“${state.text}”에서 <b>${state.tags.join(' · ')}</b>을 중요하게 파악했어요.`;$('#recommend-name').textContent=best.name;$('#metric-distance').textContent=best.distance;$('#metric-slope').textContent=best.slope;$('#metric-rest').textContent=best.rest;$('#recommend-reason').textContent=`${best.desc}. ${state.tags.includes('계단 제외')?'계단은 제외했어요.':'오늘의 이동 부담을 낮추는 균형 잡힌 선택이에요.'}`;$('#weights').textContent=Object.entries(state.score).sort((a,b)=>b[1]-a[1]).slice(0,2).map(x=>({D:'거리',S:'경사',R:'휴식'})[x[0]]).join(' · ')+' 우선';$('#route-list').innerHTML=routes.map((r,i)=>`<article class="route-option ${i===0?'chosen':''}"><div><b>${r.name}</b><span>${r.desc}</span></div><div class="route-num"><b>${r.time}</b><span>${r.slope} · 휴식 ${r.rest}</span></div></article>`).join('');show('#result-view')}
$('#back-button').onclick=()=>show('#search-view');$('#detail-button').onclick=()=>{$('#detail-title').textContent=state.best.name;show('#detail-view')};$('#result-back').onclick=()=>show('#result-view');$('#home-button').onclick=()=>show('#search-view');
